def main():
    """Generate FASTA file from PROTEINS list."""
    with open(FASTA_PATH, "w", encoding="utf-8") as f:
        for name, seq, category, function in PROTEINS:
            f.write(f">{name} | {category} | {function}\n")
            # Write sequence in 80-char lines
            for i in range(0, len(seq), 80):
                f.write(seq[i:i+80] + "\n")
    print(f"Generated {FASTA_PATH}")
    print(f"Total proteins: {len(PROTEINS)}")

    # Count by category
    from collections import Counter
    cats = Counter(c[2] for c in PROTEINS)
    for cat, count in cats.items():
        print(f"  {cat}: {count}")

    # Report sequence lengths
    lengths = [(name, len(seq)) for name, seq, _, _ in PROTEINS]
    lengths.sort(key=lambda x: x[1])
    print(f"\nSequence length range: {lengths[0][1]} - {lengths[-1][1]} aa")
    print(f"Total residues: {sum(l for _, l in lengths)}")


if __name__ == "__main__":
    main()
